/**
 * API Route: Upload de archivos para WhatsApp
 * Sube archivos a Supabase Storage y devuelve la URL pública
 * Incluye limpieza automática de archivos antiguos
 */

import { NextRequest, NextResponse } from 'next/server'
import { createClient } from '@supabase/supabase-js'

export const runtime = 'nodejs'
export const dynamic = 'force-dynamic'

// Configuración de Supabase con service role para bypass RLS
const supabaseUrl = process.env.NEXT_PUBLIC_SUPABASE_URL
const supabaseServiceKey = process.env.SUPABASE_SERVICE_ROLE_KEY || process.env.NEXT_PUBLIC_SUPABASE_ANON_KEY

const BUCKET_NAME = 'whatsapp-media'
const MAX_FILES = 500 // Máximo de archivos antes de limpiar
const MAX_AGE_DAYS = 7 // Eliminar archivos más antiguos de 7 días

// Función para limpiar archivos antiguos
// eslint-disable-next-line @typescript-eslint/no-explicit-any
async function cleanupOldFiles(supabase: any) {
  try {
    const { data: files, error } = await supabase.storage
      .from(BUCKET_NAME)
      .list('', { limit: 1000, sortBy: { column: 'created_at', order: 'asc' } })

    if (error || !files) {
      console.log('⚠️ No se pudieron listar archivos para limpieza')
      return
    }

    const now = Date.now()
    const maxAgeMs = MAX_AGE_DAYS * 24 * 60 * 60 * 1000
    const filesToDelete: string[] = []

    // Encontrar archivos antiguos
    for (const file of files) {
      if (file.created_at) {
        const fileAge = now - new Date(file.created_at).getTime()
        if (fileAge > maxAgeMs) {
          filesToDelete.push(file.name)
        }
      }
    }

    // Si hay demasiados archivos, eliminar los más antiguos
    if (files.length > MAX_FILES) {
      const excessCount = files.length - MAX_FILES + 50 // Eliminar 50 extra para dar margen
      for (let i = 0; i < excessCount && i < files.length; i++) {
        if (!filesToDelete.includes(files[i].name)) {
          filesToDelete.push(files[i].name)
        }
      }
    }

    // Eliminar archivos
    if (filesToDelete.length > 0) {
      const { error: deleteError } = await supabase.storage
        .from(BUCKET_NAME)
        .remove(filesToDelete)

      if (deleteError) {
        console.error('❌ Error eliminando archivos:', deleteError)
      } else {
        console.log(` Limpieza: ${filesToDelete.length} archivos eliminados`)
      }
    }
  } catch (error) {
    console.error('❌ Error en limpieza:', error)
  }
}

// Función para asegurar que el bucket existe y es público
// eslint-disable-next-line @typescript-eslint/no-explicit-any
async function ensureBucketExists(supabase: any): Promise<{ ok: boolean; error?: string }> {
  try {
    // Verificar si el bucket existe
    const { data: buckets, error: listError } = await supabase.storage.listBuckets()

    if (listError) {
      console.error('❌ Error listando buckets:', listError)
      return { ok: false, error: `Error listando buckets: ${listError.message}` }
    }

    const bucketExists = buckets?.some((b: any) => b.name === BUCKET_NAME)

    if (!bucketExists) {
      console.log(' Creando bucket:', BUCKET_NAME)
      const { error: createError } = await supabase.storage.createBucket(BUCKET_NAME, {
        public: true,
        fileSizeLimit: 50 * 1024 * 1024, // 50MB
        allowedMimeTypes: [
          'image/*',
          'video/*',
          'audio/*',
          'application/pdf',
          'application/msword',
          'application/vnd.openxmlformats-officedocument.wordprocessingml.document',
          'application/vnd.ms-excel',
          'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet',
          'text/plain',
          'text/csv',
        ],
      })

      if (createError) {
        console.error('❌ Error creando bucket:', createError)
        return { ok: false, error: `Error creando bucket: ${createError.message}` }
      }
      console.log('✅ Bucket creado exitosamente')
    }

    return { ok: true }
  } catch (error: any) {
    console.error('❌ Error en ensureBucketExists:', error)
    return { ok: false, error: error.message }
  }
}

export async function POST(request: NextRequest) {
  try {
    // Verificar configuración
    if (!supabaseUrl) {
      console.error('❌ NEXT_PUBLIC_SUPABASE_URL no configurado')
      return NextResponse.json(
        { ok: false, error: 'Supabase URL no configurado. Contacta al administrador.' },
        { status: 500 }
      )
    }

    if (!supabaseServiceKey) {
      console.error('❌ SUPABASE_SERVICE_ROLE_KEY no configurado')
      return NextResponse.json(
        { ok: false, error: 'Clave de Supabase no configurada. Contacta al administrador.' },
        { status: 500 }
      )
    }

    let formData: FormData
    try {
      formData = await request.formData()
    } catch (formError: any) {
      console.error('❌ Error parseando formData:', formError)
      return NextResponse.json(
        { ok: false, error: 'Error procesando el archivo. Intenta de nuevo.' },
        { status: 400 }
      )
    }

    const file = formData.get('file') as File

    if (!file) {
      return NextResponse.json(
        { ok: false, error: 'No se proporcionó archivo' },
        { status: 400 }
      )
    }

    // Validar que sea un archivo real
    if (!file.size || file.size === 0) {
      return NextResponse.json(
        { ok: false, error: 'El archivo está vacío' },
        { status: 400 }
      )
    }

    // Validar tamaño máximo (10MB)
    if (file.size > 10 * 1024 * 1024) {
      return NextResponse.json(
        { ok: false, error: 'El archivo es muy grande. Máximo 10MB.' },
        { status: 400 }
      )
    }

    console.log(' Subiendo archivo:', file.name, file.type, file.size, 'bytes')

    // Crear cliente de Supabase con service role
    const supabase = createClient(supabaseUrl, supabaseServiceKey, {
      auth: {
        autoRefreshToken: false,
        persistSession: false,
      },
    })

    // Asegurar que el bucket existe
    const bucketResult = await ensureBucketExists(supabase)
    if (!bucketResult.ok) {
      return NextResponse.json(
        { ok: false, error: bucketResult.error },
        { status: 500 }
      )
    }

    // Generar nombre único
    const timestamp = Date.now()
    const randomId = Math.random().toString(36).substring(7)
    const extension = file.name.split('.').pop() || 'bin'
    const fileName = `${timestamp}-${randomId}.${extension}`

    // Convertir File a Buffer
    let buffer: Buffer
    try {
      const arrayBuffer = await file.arrayBuffer()
      buffer = Buffer.from(arrayBuffer)
    } catch (bufferError: any) {
      console.error('❌ Error convirtiendo archivo:', bufferError)
      return NextResponse.json(
        { ok: false, error: 'Error procesando el archivo' },
        { status: 500 }
      )
    }

    // Subir archivo
    const { data: _uploadData, error } = await supabase.storage
      .from(BUCKET_NAME)
      .upload(fileName, buffer, {
        contentType: file.type || 'application/octet-stream',
        upsert: true,
      })

    if (error) {
      console.error('❌ Error subiendo a Supabase:', error)
      return NextResponse.json(
        { ok: false, error: `Error subiendo archivo: ${error.message}` },
        { status: 500 }
      )
    }

    // Obtener URL pública
    const { data: urlData } = supabase.storage
      .from(BUCKET_NAME)
      .getPublicUrl(fileName)

    if (!urlData?.publicUrl) {
      console.error('❌ No se pudo obtener URL pública')
      return NextResponse.json(
        { ok: false, error: 'Error obteniendo URL del archivo' },
        { status: 500 }
      )
    }

    console.log('✅ Archivo subido:', urlData.publicUrl)

    // Limpiar archivos antiguos en segundo plano (no bloquea la respuesta)
    cleanupOldFiles(supabase).catch(err => console.error('Error en limpieza:', err))

    return NextResponse.json({
      ok: true,
      url: urlData.publicUrl,
      filename: file.name,
      mimetype: file.type,
      size: file.size,
    })
  } catch (error: any) {
    console.error('❌ Error en upload:', error)
    return NextResponse.json(
      { ok: false, error: `Error interno: ${error.message}` },
      { status: 500 }
    )
  }
}

/**
 * API Route: Upload de archivos para WhatsApp
 * Sube archivos a Supabase Storage y devuelve la URL pública
 */

import { NextRequest, NextResponse } from 'next/server'
import { createClient } from '@supabase/supabase-js'

export const runtime = 'nodejs'
export const dynamic = 'force-dynamic'

const BUCKET_NAME = 'whatsapp-media'

export async function POST(request: NextRequest) {
  try {
    // Verificar configuración
    const supabaseUrl = process.env.NEXT_PUBLIC_SUPABASE_URL
    const supabaseKey = process.env.SUPABASE_SERVICE_ROLE_KEY || process.env.NEXT_PUBLIC_SUPABASE_ANON_KEY

    if (!supabaseUrl) {
      console.error('❌ NEXT_PUBLIC_SUPABASE_URL no configurado')
      return NextResponse.json(
        { ok: false, error: 'Supabase URL no configurado.' },
        { status: 500 }
      )
    }

    if (!supabaseKey) {
      console.error('❌ Clave de Supabase no configurada')
      return NextResponse.json(
        { ok: false, error: 'Clave de Supabase no configurada.' },
        { status: 500 }
      )
    }

    // Parsear formulario
    let formData: FormData
    try {
      formData = await request.formData()
    } catch (formError) {
      console.error('❌ Error parseando formData:', formError)
      return NextResponse.json(
        { ok: false, error: 'Error procesando el archivo.' },
        { status: 400 }
      )
    }

    const file = formData.get('file') as File

    if (!file) {
      return NextResponse.json(
        { ok: false, error: 'No se proporcionó archivo' },
        { status: 400 }
      )
    }

    if (!file.size || file.size === 0) {
      return NextResponse.json(
        { ok: false, error: 'El archivo está vacío' },
        { status: 400 }
      )
    }

    if (file.size > 10 * 1024 * 1024) {
      return NextResponse.json(
        { ok: false, error: 'El archivo es muy grande. Máximo 10MB.' },
        { status: 400 }
      )
    }

    console.log(' Subiendo archivo:', file.name, file.type, file.size, 'bytes')

    // Crear cliente de Supabase
    const supabase = createClient(supabaseUrl, supabaseKey, {
      auth: { autoRefreshToken: false, persistSession: false },
    })

    // Verificar/crear bucket
    try {
      const { data: buckets } = await supabase.storage.listBuckets()
      const bucketExists = buckets?.some((b) => b.name === BUCKET_NAME)

      if (!bucketExists) {
        console.log(' Creando bucket:', BUCKET_NAME)
        const { error: createError } = await supabase.storage.createBucket(BUCKET_NAME, {
          public: true,
          fileSizeLimit: 50 * 1024 * 1024,
        })
        if (createError) {
          console.error('❌ Error creando bucket:', createError)
          // Continuar de todos modos, puede que ya exista
        }
      }
    } catch (bucketError) {
      console.error('⚠️ Error verificando bucket:', bucketError)
      // Continuar de todos modos
    }

    // Generar nombre único
    const timestamp = Date.now()
    const randomId = Math.random().toString(36).substring(7)
    const extension = file.name.split('.').pop() || 'bin'
    const fileName = `${timestamp}-${randomId}.${extension}`

    // Convertir File a Buffer
    let buffer: Buffer
    try {
      const arrayBuffer = await file.arrayBuffer()
      buffer = Buffer.from(arrayBuffer)
    } catch (bufferError) {
      console.error('❌ Error convirtiendo archivo:', bufferError)
      return NextResponse.json(
        { ok: false, error: 'Error procesando el archivo' },
        { status: 500 }
      )
    }

    // Subir archivo
    const { error: uploadError } = await supabase.storage
      .from(BUCKET_NAME)
      .upload(fileName, buffer, {
        contentType: file.type || 'application/octet-stream',
        upsert: true,
      })

    if (uploadError) {
      console.error('❌ Error subiendo a Supabase:', uploadError)
      return NextResponse.json(
        { ok: false, error: `Error subiendo archivo: ${uploadError.message}` },
        { status: 500 }
      )
    }

    // Obtener URL pública
    const { data: urlData } = supabase.storage
      .from(BUCKET_NAME)
      .getPublicUrl(fileName)

    if (!urlData?.publicUrl) {
      console.error('❌ No se pudo obtener URL pública')
      return NextResponse.json(
        { ok: false, error: 'Error obteniendo URL del archivo' },
        { status: 500 }
      )
    }

    console.log('✅ Archivo subido:', urlData.publicUrl)

    return NextResponse.json({
      ok: true,
      url: urlData.publicUrl,
      filename: file.name,
      mimetype: file.type,
      size: file.size,
    })
  } catch (error: unknown) {
    const message = error instanceof Error ? error.message : 'Error desconocido'
    console.error('❌ Error en upload:', message)
    return NextResponse.json(
      { ok: false, error: `Error interno: ${message}` },
      { status: 500 }
    )
  }
}
